const EXT_TOKEN = (process.env && process.env.EDL_WEBHOOK_SECRET) || 'edl_wh_7Kx2mPn9sRtL';
const INT_TOKEN = (process.env && process.env.EDL_INT_SECRET) || 'edl_int_4Xp8nQfMvW2j';

function sanitize(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#x27;'}[c]))
    .replace(/[\x00-\x1F\x7F]/g, '')
    .trim()
    .substring(0, 1000);
}

const body = JSON.parse(JSON.stringify($input.first().json));

// 1. Vérification du token externe
if (!body._token || body._token !== EXT_TOKEN) {
  return [{ json: { _authFailed: true, error: 'Non autorisé' } }];
}
delete body._token;

// 2. Validation du schéma
const meta = body.meta;
if (!meta || !['entree', 'sortie'].includes(meta.type)) {
  return [{ json: { _authFailed: true, error: 'Type invalide (entree/sortie attendu)' } }];
}
if (!meta.chambre || typeof meta.chambre !== 'number' || meta.chambre < 1 || meta.chambre > 99) {
  return [{ json: { _authFailed: true, error: 'Chambre invalide (1-99)' } }];
}
if (!meta.locataire || typeof meta.locataire !== 'string' || meta.locataire.trim().length === 0 || meta.locataire.length > 200) {
  return [{ json: { _authFailed: true, error: 'Locataire invalide' } }];
}
if (!meta.date || !/^\d{4}-\d{2}-\d{2}$/.test(meta.date)) {
  return [{ json: { _authFailed: true, error: 'Date invalide (YYYY-MM-DD attendu)' } }];
}
if (!body.pieces || typeof body.pieces !== 'object' || Array.isArray(body.pieces)) {
  return [{ json: { _authFailed: true, error: 'Pièces manquantes ou invalides' } }];
}

// 3. Nettoyage XSS de tous les champs texte
meta.locataire = sanitize(meta.locataire);
if (body.observations) body.observations = sanitize(body.observations);
for (const room of Object.values(body.pieces)) {
  for (const elem of Object.values(room.elements || {})) {
    if (elem.commentaire) elem.commentaire = sanitize(elem.commentaire);
    if (elem.etat) elem.etat = sanitize(elem.etat);
  }
}

// 4. Injection du token interne (pour Agent 2)
body._intToken = INT_TOKEN;

return [{ json: body }];
